import sys

s = sys.stdin.read().split('\n')[0]
stack = []
d = {'[':']',
     '{':'}',
     '(':')',
}
flag = True
for i in range(len(s)):
    if s[i] in ['[','{','(']:
        stack.append(s[i])
    else:
        if not stack:
            flag = False
            break
        t = stack[-1]
        stack.pop()
        if s[i] != d[t]:
            flag = False
            break
if stack:
    flag = False
if flag:
    print('true')
else:
    print('false')
