# ACM 模式：用 input() 或 sys.stdin 读输入，用 print 输出答案
# 输入格式：第一行 m，第二行 m 个整数（m = 0 时为空行），第三行 n，第四行 n 个整数（n = 0 时为空行）
import sys

lines = sys.stdin.read().split('\n')
m = int(lines[0])
nums1 = list(map(int, lines[1].split())) if m > 0 else []
n = int(lines[2])
nums2 = list(map(int, lines[3].split())) if n > 0 else []


def get(k):
    index1,index2 = 0,0
    while 1:
        if index1 == m:
            return nums2[index2+k-1]
        if index2 == n:
            return nums1[index1+k-1]
        if k==1:
            return min(nums1[index1],nums2[index2])
        new1,new2 = min(index1+k//2-1,m-1),min(index2+k//2-1,n-1)
        if nums1[new1] < nums2[new2]:
            k -= new1-index1+1
            index1 = new1+1 
        else:
            k -= new2-index2+1
            index2 = new2+1
total = m+n
if total%2==1:
    print(float(get(total//2+1)))
else:
    print(float((get(total//2)+get(total//2+1))/2))
# 在这里写你的代码，用 print 输出中位数

